#!/usr/bin/env python3
"""Install Cloudflare real_ip restore for nginx (safe with or without CF proxy)."""
from __future__ import annotations

import pathlib
import sys

import paramiko

HOST = "94.249.244.208"
USER = "taranom"
REMOTE = "/etc/nginx/conf.d/cloudflare-realip.conf"

CONF = """# Cloudflare real IP restore — erp-taranom / erptaranom.com
# Regenerated by scripts/_apply-cf-realip-erptaranom.py
real_ip_header CF-Connecting-IP;
real_ip_recursive on;
"""


def p(s: str) -> None:
    sys.stdout.write(s.encode("ascii", "replace").decode("ascii") + "\n")
    sys.stdout.flush()


def find_key() -> pathlib.Path:
    for cand in (
        pathlib.Path.home() / ".ssh" / "id_ed25519_taranom",
        pathlib.Path(r"D:\proje\.ssh\id_ed25519_taranom"),
    ):
        if cand.exists():
            return cand
    raise SystemExit("SSH key not found")


def main() -> int:
    client = paramiko.SSHClient()
    client.set_missing_host_key_policy(paramiko.AutoAddPolicy())
    client.connect(HOST, username=USER, key_filename=str(find_key()), timeout=30)

    def run(cmd: str, timeout: int = 60) -> tuple[int, str]:
        _i, stdout, stderr = client.exec_command(cmd, timeout=timeout)
        out = stdout.read().decode("utf-8", "replace") + stderr.read().decode("utf-8", "replace")
        return stdout.channel.recv_exit_status(), out

    # Fetch CF CIDRs from the VPS (local Windows proxy often 403s cloudflare.com/ips-*)
    code, raw = run(
        "curl -fsS https://www.cloudflare.com/ips-v4; echo; "
        "curl -fsS https://www.cloudflare.com/ips-v6"
    )
    if code != 0:
        p("fetch cidrs failed: " + raw)
        return 1
    cidrs = [ln.strip() for ln in raw.splitlines() if ln.strip() and not ln.startswith("<")]
    p(f"cidrs={len(cidrs)}")
    body = CONF + "\n".join(f"set_real_ip_from {c};" for c in cidrs) + "\n"

    sftp = client.open_sftp()
    with sftp.file("/tmp/cloudflare-realip.conf", "w") as f:
        f.write(body)
    sftp.close()

    for cmd in (
        f"sudo cp -a {REMOTE} {REMOTE}.bak 2>/dev/null || true",
        f"sudo cp /tmp/cloudflare-realip.conf {REMOTE}",
        "sudo nginx -t",
        "sudo systemctl reload nginx",
        "curl -sS -o /dev/null -w 'health:%{http_code}\\n' -H 'Host: erptaranom.com' https://127.0.0.1/api/system/health --insecure",
    ):
        code, out = run(cmd)
        p(f"$ {cmd}\nexit={code}\n{out}")
        if code != 0 and "nginx -t" in cmd:
            run(f"sudo cp -a {REMOTE}.bak {REMOTE} 2>/dev/null || sudo rm -f {REMOTE}")
            run("sudo nginx -t && sudo systemctl reload nginx")
            client.close()
            return 1

    client.close()
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
